export type SubscribeFn = <A extends any[], R = void>(listener: Listener<A, R>) => () => void;

export interface EventManager {
    setEventID: (eventID: string) => void;
    getEventID: () => string | undefined;
    start: () => void;
    stop: () => void;
    call: () => Promise<void>;
